R = Path(__file__).resolve().parents[1]

def read(p):
    return json.loads((R / p).read_text())

def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()

def write(p, x):
    (R / p).write_text(json.dumps(x, indent=2, allow_nan=False, ensure_ascii=False))

